require_relative 'driver'
fresh('shapes');shot('shapes-before')
run('a=below(function(x)return 80 end);z=above(function(x)return 80 end);r1=ribbon({{100,50},{200,80}},10);r2=ribbon({{100,50},{200,80}},{10,10});print(a:at(150,20),a:at(150,150),z:at(150,20),z:at(150,150),r1:area(),r2:area());m=rect(300,40,200,100);print(m:area());for _,n in ipairs{"grow","shrink","offset","rim","blur","soften"} do local d=m[n](m,10);print(n,d:area(),m:area(),d:at(305,80),d:at(295,80)) end;d=m:distance();print("distance",d:at(400,80),d:at(200,80),d:band(-5,5,0):area());e=mask(function(x,y)return x/1000 end);print("clamp",e:at(-100,80),e:at(0,80),e:at(1001,80),e:at(10000,80));k=0.25;s=mask(function()return k end);k=0.75;t=mask(function()return k end);print("fixed",s:at(400,80),t:at(400,80))')
run('pts={{200,30},{400,30},{450,140},{250,140}};for _,k in ipairs{false,true} do local o=outline{pts=pts,corners=k,seed=1};print("corners",k,#o:corners()) end;for _,indices in ipairs{{1},{1,3}} do local o=outline{pts=pts,corners=indices,seed=1};print("indices",#o:corners()) end;marked=outline{pts={{200,30,"c"},{400,30},{450,140},{250,140}},seed=1};print("marked",#marked:corners());polyplain=poly(pts);polysmooth=poly(pts,true);print("polygon",polyplain:area(),polysmooth:area())')
run('outline{pts=pts,corners={99}}')
run('for _,k in ipairs{"firm","searching","broken","soft"} do local o=outline{pts=pts,char=k,seed=1};print(k,#o:path(),#o:paths(),#o:strokes(),#o:corners(),o:length(),o:mask():area(),o.closed,o.scale);local x,y,tx,ty,nx,ny=o:at(0.5);print("at",x,y,tx,ty,nx,ny); _G[k]=o end;print("default",outline{pts=pts,seed=1}:length(),firm:length());print("derived",firm:below():area(),firm:above():area(),firm:band(5,1):area(),firm:inset(2):mask():area(),firm:offset(2):mask():area())')
run('blob=body_of{spine={{400,80}},widths=40};print("blob",blob:mask():area());sp={{200,80},{500,80}};limb={pts={{350,80},{350,140}},widths={20,10}};for _,v in ipairs{0,0.8,1} do local b=body_of{spine=sp,widths={40,30},limbs={limb},blend=v};print("body",v,b:mask():area()) end')
['body_of{spine={},widths=1}','body_of{spine={{1,1},{2,2}}}','body_of{spine={{1,1},{2,2},{3,3}},widths={1,2}}','body_of{spine={{1,1}},widths=20,limbs={{pts={{1,1}},widths=2}}}'].each{|s|run(s)}
run('for _,n in ipairs{0.9,1} do local ok,v=pcall(function()return outline{pts=pts,size=n}:length() end);print("size",n,ok,v) end;for _,n in ipairs{0,0.49,0.5} do local ok,v=pcall(function()return outline{pts=pts,lobe=n}:length() end);print("lobe",n,ok,v) end;print("zeroamount",outline{pts=pts,amount=0,lobe=20}:length(),outline{pts=pts,amount=0,lobe=0}:length())')
run('print("helpers",lerp(2,4,0.5),clamp(-1),clamp(2),smoothstep(0,1,0.5));for i=1,5 do print("random",rand(),rand(4),rand(2,4),randn()) end;for _,k in ipairs{"fbm","ridged","billow","plain"} do local ok,n=pcall(function()return noise{kind=k,seed=1} end);print("noise",k,ok);if ok then print(n(100,80),n:at(100,80),n:at01(100,80)) end end;n=noise{seed=1};print("defaultnoise",n(100,80),noise{seed=1,octaves=4,period=200}(100,80));print("warped",noise{seed=1,warp={100,20,true},stretch={0.5,2}}(100,80));w=worley{seed=1};print("worley",w(100,80));print(w:at(100,80));print(worley{seed=1,period=40}:at(100,80));print("uneven",table.concat(uneven(10,100,900),","),table.concat(uneven(10,100,900,0.6,0.3,1),","),table.concat(uneven(10,100,900,0.6,0.3,2),","))')
shot('shapes-after')
%w[firm searching broken soft].each{|ch|case_image('outline-'+ch,'pts={{200,30},{400,30},{450,140},{250,140}};b=brush("round",4);',"o=outline{pts=pts,char=\"#{ch}\",seed=1};n=#o:strokes();len=o:length();print(o:paint(b,{dip={p,0.6},every=3}),b:fullness());print(n,#o:strokes(),len,o:length());work(o:mask(),{pile=p,hand=\"glaze\",coverage=0.2,seed=1})")}
{'amount'=>'amount=0','size'=>'size=20','lobe'=>'lobe=20','edge'=>'edge=10','seed'=>'seed=2'}.each{|k,v|case_image('outline-'+k,'pts={{200,30},{400,30},{450,140},{250,140}};',"o=outline{pts=pts,#{v}};print(o:length(),o:mask():area());work(o:mask(),{pile=p,hand=\"detail\",clip=true,coverage=1,seed=1})")}
cli('close')
